export const dynamic = 'force-static';

const PAGE_HTML: string = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\" />\n  <meta name=\"theme-color\" content=\"#F7F2E7\" />\n  <title>灯下白FDE案例展示——南方康复学校脑瘫儿童课程定制项目</title>\n  <meta name=\"description\" content=\"灯下白FDE案例展示：面向南方某康复学校1名教师与15名脑瘫及特教需求儿童，定制交付10节A/B/C三档分层本地HTML多模态互动课程。\" />\n  <meta property=\"og:type\" content=\"article\" />\n  <meta property=\"og:title\" content=\"灯下白FDE案例展示——南方康复学校脑瘫儿童课程定制项目\" />\n  <meta property=\"og:description\" content=\"面向南方某康复学校1名教师与15名特教及脑瘫康复需求儿童，35天定制交付10节A/B/C三档分层本地HTML多模态互动课程。\" />\n  <meta property=\"og:url\" content=\"https://ka21.org/fde-cases/nanfang-rehab\" />\n  <link rel=\"canonical\" href=\"https://ka21.org/fde-cases/nanfang-rehab\" />\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,600;0,700;1,500;1,600&family=Noto+Serif+SC:wght@600;700&display=swap\" rel=\"stylesheet\" media=\"print\" onload=\"this.media='all'\" />\n  <style>\n/* ==========================================================================\n   灯下白 · FDE 案例手记\n   法式纸本水粉插画风 —— 桌面端杂志跨页与移动端手账双端响应式系统\n   ========================================================================== */\n\n:root {\n  /* Paper & Desk Surfaces */\n  --desk-linen: #E5DDD0;\n  --paper: #F7F2E7;\n  --paper-deep: #EFE7D6;\n  --paper-ivory: #FCF9F2;\n  --paper-tint-blue: #EBF0F5;\n  --paper-tint-ochre: #F9F0D9;\n  --paper-tint-rose: #F6E7E1;\n  --paper-tint-sage: #E8EFE6;\n\n  /* Ink Tones (Warm Sepia Charcoal — Never Pure #000) */\n  --ink: #27231F;\n  --ink-body: #38322C;\n  --ink-soft: #625A50;\n  --ink-muted: #8A8073;\n  --rule: rgba(39, 35, 31, 0.15);\n  --rule-strong: rgba(39, 35, 31, 0.42);\n\n  /* Gouache Pigments */\n  --terracotta: #C25941;\n  --terracotta-wash: #F2DAD2;\n  --cobalt: #33588A;\n  --cobalt-wash: #D8E4F2;\n  --ochre: #D59B32;\n  --ochre-wash: #F7E7BE;\n  --sage: #557653;\n  --sage-wash: #DCE9DA;\n\n  /* Typography */\n  --font-serif-cn: \"Songti SC\", \"STSong\", \"Noto Serif SC\", \"Source Han Serif SC\", \"SimSun\", serif;\n  --font-display-num: \"Cormorant Garamond\", \"Baskerville\", \"Palatino Linotype\", \"Book Antiqua\", Georgia, serif;\n  --font-sans-cn: \"PingFang SC\", \"Hiragino Sans GB\", -apple-system, BlinkMacSystemFont, \"Noto Sans SC\", \"Microsoft YaHei\", sans-serif;\n\n  /* Layout Rhythm (Mobile Default, Expanded on Tablet/Desktop) */\n  --sheet-max: 1100px;\n  --gutter: 22px;\n}\n\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nhtml {\n  scroll-behavior: smooth;\n  -webkit-text-size-adjust: 100%;\n  background-color: var(--desk-linen);\n}\n\nbody {\n  margin: 0;\n  padding: 0;\n  background-color: var(--desk-linen);\n  color: var(--ink-body);\n  font-family: var(--font-sans-cn);\n  font-size: 16px;\n  line-height: 1.86;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n  overflow-x: clip;\n}\n\n/* Subtle Reading Progress Hairline */\n.reading-progress {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 3px;\n  z-index: 60;\n  pointer-events: none;\n  background: transparent;\n}\n\n.reading-progress__bar {\n  height: 100%;\n  width: 0%;\n  background: linear-gradient(90deg, var(--cobalt), var(--terracotta), var(--ochre));\n  transition: width 80ms linear;\n}\n\n/* Main Editorial Sheet */\n.carnet-sheet {\n  position: relative;\n  width: 100%;\n  max-width: var(--sheet-max);\n  margin: 0 auto;\n  background-color: var(--paper);\n  min-height: 100dvh;\n  padding-bottom: calc(48px + env(safe-area-inset-bottom, 0px));\n}\n\n@media (min-width: 768px) {\n  :root {\n    --gutter: 44px;\n  }\n\n  body {\n    padding: 28px 24px 56px;\n    background-image: radial-gradient(rgba(39, 35, 31, 0.055) 1px, transparent 0);\n    background-size: 22px 22px;\n  }\n\n  .carnet-sheet {\n    border: 1px solid rgba(39, 35, 31, 0.15);\n    border-radius: 6px;\n    box-shadow:\n      0 22px 60px rgba(39, 35, 31, 0.10),\n      0 2px 8px rgba(39, 35, 31, 0.05);\n  }\n}\n\n@media (min-width: 1024px) {\n  :root {\n    --gutter: 64px;\n  }\n\n  body {\n    padding: 36px 32px 68px;\n  }\n}\n\n/* Subtle Archival Cotton Paper Texture Overlay */\n.paper-grain {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  z-index: 50;\n  opacity: 0.032;\n  background-image: url(\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E\");\n}\n\n/* Hidden SVG Filter Library */\n.svg-defs-vault {\n  position: absolute;\n  width: 0;\n  height: 0;\n  overflow: hidden;\n  pointer-events: none;\n}\n\n/* ==========================================================================\n   Editorial Top Masthead & Cover\n   ========================================================================== */\n\n.cover {\n  padding: 18px var(--gutter) 28px;\n  position: relative;\n}\n\n@media (min-width: 900px) {\n  .cover {\n    padding: 28px var(--gutter) 44px;\n  }\n}\n\n.masthead-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-bottom: 10px;\n  border-bottom: 1.5px solid var(--ink);\n  position: relative;\n  font-size: 12.5px;\n  letter-spacing: 0.06em;\n  color: var(--ink-soft);\n}\n\n.masthead-bar::after {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: -4px;\n  border-bottom: 0.75px solid var(--rule-strong);\n}\n\n.masthead-brand {\n  font-family: var(--font-serif-cn);\n  font-weight: 700;\n  color: var(--ink);\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n}\n\n.masthead-dot {\n  display: inline-block;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background-color: var(--terracotta);\n}\n\n.masthead-folio {\n  font-family: var(--font-serif-cn);\n  font-size: 12.5px;\n  letter-spacing: 0.05em;\n  color: var(--ink-soft);\n}\n\n/* Responsive Cover Spread */\n.cover-spread {\n  display: flex;\n  flex-direction: column;\n}\n\n@media (min-width: 900px) {\n  .cover-spread {\n    display: grid;\n    grid-template-columns: 1.12fr 0.88fr;\n    gap: 44px;\n    align-items: center;\n    margin-top: 34px;\n  }\n\n  .cover-copy {\n    order: 1;\n  }\n\n  .cover-illustration {\n    order: 2;\n    margin: 0 !important;\n    max-width: 100% !important;\n    padding: 24px 20px 16px;\n    background-color: var(--paper-ivory);\n    border: 1.2px solid var(--rule-strong);\n    border-radius: 6px 12px 8px 10px;\n    box-shadow: 6px 8px 0 rgba(213, 155, 50, 0.16);\n  }\n}\n\n.cover-illustration {\n  margin: 22px auto 18px;\n  position: relative;\n  max-width: 390px;\n  width: 100%;\n}\n\n.cover-illustration svg {\n  width: 100%;\n  height: auto;\n  display: block;\n  overflow: visible;\n}\n\n.cover-kicker {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  margin: 2px 0 12px;\n  padding: 4px 12px 4px 10px;\n  background-color: var(--ochre-wash);\n  border: 1px solid rgba(39, 35, 31, 0.22);\n  border-radius: 2px 7px 3px 6px;\n  font-family: var(--font-serif-cn);\n  font-size: 12.5px;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  color: var(--ink);\n  box-shadow: 2px 2px 0 rgba(213, 155, 50, 0.28);\n}\n\n.cover-title {\n  margin: 0;\n  font-family: var(--font-serif-cn);\n  font-weight: 700;\n  line-height: 1.38;\n  color: var(--ink);\n  letter-spacing: 0.01em;\n}\n\n.cover-title__eyebrow {\n  display: block;\n  font-size: clamp(17.5px, 4.6vw, 21px);\n  color: var(--ink);\n  margin-bottom: 5px;\n}\n\n.cover-title__sub {\n  display: block;\n  font-size: clamp(23.5px, 6.2vw, 31px);\n  line-height: 1.34;\n  color: var(--cobalt);\n  position: relative;\n}\n\n@media (min-width: 900px) {\n  .cover-title__eyebrow {\n    font-size: clamp(18px, 1.9vw, 22px);\n  }\n\n  .cover-title__sub {\n    font-size: clamp(26px, 2.9vw, 34px);\n  }\n}\n\n.cover-brush-underline {\n  display: block;\n  width: 176px;\n  height: 10px;\n  margin-top: 8px;\n}\n\n.cover-lead {\n  margin: 16px 0 0;\n  font-size: 15.5px;\n  line-height: 1.84;\n  color: var(--ink-soft);\n  text-wrap: pretty;\n  max-width: 560px;\n}\n\n/* Cover Key Metadata Strip */\n.cover-meta-row {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 8px;\n  margin-top: 22px;\n  padding-top: 16px;\n  border-top: 1px dashed var(--rule-strong);\n}\n\n@media (min-width: 900px) {\n  .cover-meta-row {\n    gap: 18px;\n    margin-top: 26px;\n    padding-top: 18px;\n  }\n}\n\n.meta-cell {\n  text-align: left;\n  padding-right: 4px;\n}\n\n.meta-cell:not(:last-child) {\n  border-right: 1px solid var(--rule);\n}\n\n.meta-cell__label {\n  display: block;\n  font-size: 11.5px;\n  color: var(--ink-muted);\n  letter-spacing: 0.03em;\n  margin-bottom: 3px;\n  white-space: nowrap;\n}\n\n.meta-cell__val {\n  font-family: var(--font-serif-cn);\n  font-weight: 700;\n  font-size: 13.8px;\n  color: var(--ink);\n  white-space: nowrap;\n}\n\n@media (min-width: 768px) {\n  .meta-cell__label {\n    font-size: 12.5px;\n  }\n  .meta-cell__val {\n    font-size: 16.5px;\n  }\n}\n\n/* ==========================================================================\n   Sticky Chapter Ribbon (Mobile Compact 6-Grid / Desktop Full Bar)\n   ========================================================================== */\n\n.chapter-nav {\n  position: sticky;\n  top: 0;\n  z-index: 40;\n  background-color: rgba(247, 242, 231, 0.94);\n  backdrop-filter: blur(8px);\n  -webkit-backdrop-filter: blur(8px);\n  border-top: 1px solid var(--rule);\n  border-bottom: 1px solid var(--rule-strong);\n  padding: 7px 12px;\n}\n\n.chapter-nav__list {\n  display: grid;\n  grid-template-columns: repeat(6, 1fr);\n  gap: 3px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  width: 100%;\n}\n\n.nav-extra {\n  display: none;\n}\n\n.chapter-nav__link {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 2px;\n  padding: 5px 2px;\n  border-radius: 999px;\n  text-decoration: none;\n  font-size: 12.5px;\n  font-weight: 500;\n  color: var(--ink-soft);\n  border: 1px solid transparent;\n  transition: background-color 0.18s ease, color 0.18s ease, border-color 0.18s ease;\n  white-space: nowrap;\n}\n\n.chapter-nav__num {\n  font-family: var(--font-display-num);\n  font-style: italic;\n  font-size: 12px;\n  color: var(--ink-muted);\n}\n\n@media (min-width: 768px) {\n  .chapter-nav {\n    padding: 10px var(--gutter);\n  }\n\n  .chapter-nav__list {\n    gap: 10px;\n  }\n\n  .nav-extra {\n    display: inline;\n  }\n\n  .chapter-nav__link {\n    gap: 6px;\n    padding: 7px 12px;\n    font-size: 14px;\n  }\n\n  .chapter-nav__num {\n    font-size: 15px;\n  }\n}\n\n.chapter-nav__link.is-active {\n  background-color: var(--paper-ivory);\n  color: var(--ink);\n  border-color: var(--rule-strong);\n  box-shadow: 1px 1.5px 0 rgba(39, 35, 31, 0.12);\n  font-weight: 600;\n}\n\n.chapter-nav__link.is-active .chapter-nav__num {\n  color: var(--terracotta);\n}\n\n/* ==========================================================================\n   Shared Chapter Typography & Ornaments\n   ========================================================================== */\n\n.chapter {\n  padding: 36px var(--gutter) 34px;\n  position: relative;\n  scroll-margin-top: 56px;\n}\n\n@media (min-width: 900px) {\n  .chapter {\n    padding: 54px var(--gutter) 52px;\n    scroll-margin-top: 64px;\n  }\n}\n\n.chapter--tinted-warm {\n  background-color: var(--paper-deep);\n}\n\n.deckle-divider {\n  display: block;\n  width: 100%;\n  height: 14px;\n  overflow: hidden;\n  line-height: 0;\n}\n\n.deckle-divider svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.chapter-header {\n  margin-bottom: 18px;\n}\n\n.chapter-rubric {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 6px;\n}\n\n.chapter-num-badge {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--font-display-num);\n  font-style: italic;\n  font-weight: 700;\n  font-size: 24px;\n  line-height: 1;\n  color: var(--ink);\n  z-index: 1;\n  padding: 2px 6px;\n}\n\n.chapter-num-badge::before {\n  content: \"\";\n  position: absolute;\n  inset: 2px -2px 0px 2px;\n  border-radius: 52% 48% 44% 56% / 48% 55% 45% 52%;\n  z-index: -1;\n  background-color: var(--terracotta-wash);\n}\n\n.chapter-num-badge--blue::before {\n  background-color: var(--cobalt-wash);\n}\n\n.chapter-num-badge--ochre::before {\n  background-color: var(--ochre-wash);\n}\n\n.chapter-num-badge--sage::before {\n  background-color: var(--sage-wash);\n}\n\n.chapter-sub-cn {\n  font-family: var(--font-serif-cn);\n  font-size: 13px;\n  letter-spacing: 0.06em;\n  color: var(--ink-muted);\n}\n\n.chapter-title {\n  margin: 0;\n  font-family: var(--font-serif-cn);\n  font-weight: 700;\n  font-size: clamp(22px, 3vw, 27px);\n  line-height: 1.38;\n  color: var(--ink);\n}\n\n.prose-p {\n  margin: 0 0 14px;\n  font-size: 16px;\n  line-height: 1.88;\n  color: var(--ink-body);\n  text-wrap: pretty;\n}\n\n.prose-p:last-child {\n  margin-bottom: 0;\n}\n\n.gouache-hl {\n  background: linear-gradient(180deg, transparent 56%, var(--ochre-wash) 56%);\n  padding: 0 2px;\n  color: var(--ink);\n  font-weight: 600;\n}\n\n.gouache-hl--rose {\n  background: linear-gradient(180deg, transparent 56%, var(--terracotta-wash) 56%);\n}\n\n.gouache-hl--blue {\n  background: linear-gradient(180deg, transparent 56%, var(--cobalt-wash) 56%);\n}\n\n/* ==========================================================================\n   Chapter 01: 甲方 · 1 名教师与 15 名学生插画卡\n   ========================================================================== */\n\n.client-layout {\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n@media (min-width: 860px) {\n  .client-layout {\n    display: grid;\n    grid-template-columns: 0.95fr 1.05fr;\n    gap: 42px;\n    align-items: center;\n  }\n}\n\n.classroom-sketch-card {\n  margin: 2px 0;\n  padding: 18px 18px 16px;\n  background-color: var(--paper-ivory);\n  border: 1.2px solid var(--ink);\n  border-radius: 4px 10px 5px 8px;\n  box-shadow: 4px 5px 0 var(--cobalt-wash);\n  position: relative;\n}\n\n.classroom-sketch-card svg {\n  width: 100%;\n  height: auto;\n  display: block;\n  margin-bottom: 12px;\n}\n\n.scale-stats {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 12px;\n  padding-top: 12px;\n  border-top: 1px dashed var(--rule-strong);\n}\n\n.scale-stat {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n}\n\n.scale-stat__num {\n  font-family: var(--font-display-num);\n  font-weight: 700;\n  font-size: 32px;\n  line-height: 1;\n  color: var(--terracotta);\n}\n\n.scale-stat--students .scale-stat__num {\n  color: var(--cobalt);\n}\n\n.scale-stat__unit {\n  font-family: var(--font-serif-cn);\n  font-size: 14.5px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.scale-stat__desc {\n  display: block;\n  font-size: 12.5px;\n  color: var(--ink-soft);\n  margin-top: 2px;\n}\n\n/* ==========================================================================\n   Chapter 02: 难题 · 四项具体问题 (Stack on Mobile, 2x2 Ledger on Desktop)\n   ========================================================================== */\n\n.problem-top-grid {\n  margin-bottom: 18px;\n}\n\n@media (min-width: 860px) {\n  .problem-top-grid {\n    display: grid;\n    grid-template-columns: 0.95fr 1.05fr;\n    gap: 36px;\n    align-items: end;\n    margin-bottom: 28px;\n  }\n\n  .contrast-banner {\n    margin-bottom: 0 !important;\n  }\n}\n\n.contrast-banner {\n  margin: 16px 0 18px;\n  padding: 15px 16px;\n  background-color: var(--paper-ivory);\n  border-left: 3px solid var(--terracotta);\n  border-top: 1px solid var(--rule);\n  border-right: 1px solid var(--rule);\n  border-bottom: 1px solid var(--rule);\n  border-radius: 0 8px 6px 0;\n}\n\n.contrast-banner__lead {\n  margin: 0;\n  font-family: var(--font-serif-cn);\n  font-size: 15.5px;\n  line-height: 1.78;\n  color: var(--ink);\n}\n\n.problem-ledger {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.problem-item {\n  display: grid;\n  grid-template-columns: 52px 1fr;\n  gap: 12px;\n  padding: 18px 0;\n  border-top: 1px solid var(--rule-strong);\n  align-items: start;\n}\n\n.problem-item:last-child {\n  border-bottom: 1px solid var(--rule-strong);\n}\n\n@media (min-width: 860px) {\n  .problem-ledger {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 0 40px;\n  }\n\n  .problem-item:nth-child(3) {\n    border-bottom: 1px solid var(--rule-strong);\n  }\n}\n\n.problem-item__illus {\n  width: 48px;\n  height: 48px;\n  flex-shrink: 0;\n}\n\n.problem-item__illus svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n  overflow: visible;\n}\n\n.problem-item__head {\n  display: flex;\n  align-items: baseline;\n  gap: 7px;\n  margin: 0 0 5px;\n}\n\n.problem-item__idx {\n  font-family: var(--font-display-num);\n  font-style: italic;\n  font-weight: 600;\n  font-size: 17px;\n  color: var(--terracotta);\n}\n\n.problem-item__title {\n  margin: 0;\n  font-family: var(--font-serif-cn);\n  font-weight: 700;\n  font-size: 17px;\n  color: var(--ink);\n}\n\n.problem-item__desc {\n  margin: 0;\n  font-size: 15px;\n  line-height: 1.78;\n  color: var(--ink-soft);\n  text-wrap: pretty;\n}\n\n/* ==========================================================================\n   Chapter 03: 交付内容 · A/B/C 抽认卡 + 本地 HTML 备忘 + 多模态 + 10节课程邮票\n   ========================================================================== */\n\n.delivery-lead {\n  max-width: 760px;\n}\n\n.delivery-feature-split {\n  display: flex;\n  flex-direction: column;\n  gap: 22px;\n  margin: 20px 0 6px;\n}\n\n@media (min-width: 860px) {\n  .delivery-feature-split {\n    display: grid;\n    grid-template-columns: 1.12fr 0.88fr;\n    gap: 28px;\n    align-items: end;\n    margin: 24px 0 12px;\n  }\n}\n\n.tier-showcase {\n  margin: 0;\n}\n\n.tier-showcase__caption {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: 12.5px;\n  color: var(--ink-muted);\n  margin-bottom: 8px;\n}\n\n.tier-tabs {\n  display: flex;\n  gap: 6px;\n  padding: 0 6px;\n  position: relative;\n  z-index: 2;\n}\n\n.tier-tab {\n  appearance: none;\n  border: 1.2px solid var(--ink);\n  border-bottom: none;\n  background-color: var(--paper-deep);\n  color: var(--ink-soft);\n  padding: 8px 14px 7px;\n  border-radius: 8px 10px 0 0;\n  font-family: var(--font-serif-cn);\n  font-size: 14px;\n  font-weight: 700;\n  cursor: pointer;\n  transition: transform 0.18s ease, background-color 0.18s ease;\n  min-height: 40px;\n}\n\n.tier-tab[data-tier=\"A\"].is-selected {\n  background-color: var(--paper-tint-ochre);\n  color: var(--ink);\n  transform: translateY(1.5px);\n}\n\n.tier-tab[data-tier=\"B\"].is-selected {\n  background-color: var(--paper-tint-blue);\n  color: var(--ink);\n  transform: translateY(1.5px);\n}\n\n.tier-tab[data-tier=\"C\"].is-selected {\n  background-color: var(--paper-tint-sage);\n  color: var(--ink);\n  transform: translateY(1.5px);\n}\n\n.tier-card-stage {\n  border: 1.2px solid var(--ink);\n  border-radius: 3px 10px 8px 6px;\n  padding: 18px;\n  background-color: var(--paper-tint-ochre);\n  box-shadow: 4px 4px 0 rgba(39, 35, 31, 0.10);\n  transition: background-color 0.25s ease;\n}\n\n.tier-card-stage[data-active-tier=\"B\"] {\n  background-color: var(--paper-tint-blue);\n}\n\n.tier-card-stage[data-active-tier=\"C\"] {\n  background-color: var(--paper-tint-sage);\n}\n\n.tier-panel {\n  display: none;\n}\n\n.tier-panel.is-visible {\n  display: block;\n  animation: fadeSlideIn 0.24s ease;\n}\n\n@keyframes fadeSlideIn {\n  from {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n.tier-panel__badge {\n  display: inline-block;\n  font-family: var(--font-serif-cn);\n  font-weight: 600;\n  font-size: 12.5px;\n  padding: 2px 9px;\n  border: 1px solid var(--rule-strong);\n  border-radius: 999px;\n  background-color: rgba(252, 249, 242, 0.8);\n  color: var(--ink);\n  margin-bottom: 8px;\n}\n\n.tier-panel__title {\n  margin: 0 0 6px;\n  font-family: var(--font-serif-cn);\n  font-size: 17.5px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.tier-panel__text {\n  margin: 0;\n  font-size: 14.5px;\n  line-height: 1.78;\n  color: var(--ink-body);\n  text-wrap: pretty;\n}\n\n/* Paperclip Field Memo: Why Local HTML? */\n.atelier-memo {\n  position: relative;\n  margin: 6px 0 0;\n  padding: 20px 18px 18px;\n  background-color: var(--paper-tint-blue);\n  border: 1px solid rgba(51, 88, 138, 0.32);\n  border-radius: 3px 9px 4px 7px;\n}\n\n.atelier-memo__clip {\n  position: absolute;\n  top: -13px;\n  right: 20px;\n  width: 26px;\n  height: 44px;\n  pointer-events: none;\n}\n\n.atelier-memo__title {\n  margin: 0 0 8px;\n  font-family: var(--font-serif-cn);\n  font-weight: 700;\n  font-size: 16.5px;\n  color: var(--cobalt);\n}\n\n.atelier-memo__p {\n  margin: 0 0 10px;\n  font-size: 14.8px;\n  line-height: 1.8;\n  color: var(--ink-body);\n  text-wrap: pretty;\n}\n\n.atelier-memo__p:last-child {\n  margin-bottom: 0;\n}\n\n/* 4 Multimodal Content Blocks */\n.modality-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 12px;\n  margin: 12px 0 28px;\n}\n\n@media (min-width: 860px) {\n  .modality-grid {\n    grid-template-columns: repeat(4, 1fr);\n    gap: 16px;\n    margin: 14px 0 34px;\n  }\n}\n\n.modality-card {\n  padding: 15px 14px 14px;\n  background-color: var(--paper-ivory);\n  border: 1px solid var(--rule-strong);\n  border-radius: 6px 3px 8px 4px;\n  position: relative;\n}\n\n.modality-card:nth-child(1) { box-shadow: 3px 3px 0 var(--ochre-wash); }\n.modality-card:nth-child(2) { box-shadow: 3px 3px 0 var(--terracotta-wash); }\n.modality-card:nth-child(3) { box-shadow: 3px 3px 0 var(--cobalt-wash); }\n.modality-card:nth-child(4) { box-shadow: 3px 3px 0 var(--sage-wash); }\n\n.modality-card__icon {\n  width: 34px;\n  height: 34px;\n  margin-bottom: 6px;\n}\n\n.modality-card__icon svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.modality-card__title {\n  margin: 0 0 4px;\n  font-family: var(--font-serif-cn);\n  font-size: 16px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.modality-card__desc {\n  margin: 0;\n  font-size: 13.8px;\n  line-height: 1.68;\n  color: var(--ink-soft);\n}\n\n/* Illustrated Course Postage Stamps */\n.course-shelf-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin: 26px 0 12px;\n}\n\n.course-shelf-title {\n  margin: 0;\n  font-family: var(--font-serif-cn);\n  font-size: 17.5px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.course-shelf-sub {\n  font-size: 12.5px;\n  color: var(--ink-muted);\n  white-space: nowrap;\n}\n\n.stamp-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 12px;\n}\n\n@media (min-width: 768px) {\n  .stamp-grid {\n    grid-template-columns: repeat(3, 1fr);\n    gap: 16px;\n  }\n}\n\n.course-stamp {\n  background-color: var(--paper-ivory);\n  padding: 14px 12px 13px;\n  border: 1px dashed rgba(39, 35, 31, 0.34);\n  border-radius: 4px;\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n  box-shadow: 0 2px 0 rgba(39, 35, 31, 0.06);\n}\n\n.course-stamp::before {\n  content: \"\";\n  position: absolute;\n  inset: 4px;\n  border: 0.75px solid rgba(39, 35, 31, 0.14);\n  pointer-events: none;\n}\n\n.course-stamp__art {\n  width: 68px;\n  height: 58px;\n  margin-bottom: 6px;\n}\n\n.course-stamp__art svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n  overflow: visible;\n}\n\n.course-stamp__num {\n  font-family: var(--font-serif-cn);\n  font-size: 11.5px;\n  letter-spacing: 0.05em;\n  color: var(--ink-muted);\n  line-height: 1.2;\n}\n\n.course-stamp__name {\n  margin: 4px 0 0;\n  font-family: var(--font-serif-cn);\n  font-weight: 700;\n  font-size: 15px;\n  color: var(--ink);\n}\n\n.course-stamp--more {\n  grid-column: 1 / -1;\n  flex-direction: row;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n  text-align: left;\n  padding: 14px 18px;\n  background-color: var(--paper-tint-ochre);\n  border-style: solid;\n  border-color: rgba(39, 35, 31, 0.25);\n}\n\n.course-stamp--more .course-stamp__name {\n  font-size: 14.8px;\n  margin: 2px 0 0;\n}\n\n.course-stamp__tag {\n  font-family: var(--font-serif-cn);\n  font-size: 12.5px;\n  font-weight: 700;\n  color: var(--terracotta);\n  background-color: var(--paper-ivory);\n  padding: 4px 10px;\n  border: 1px solid rgba(194, 89, 65, 0.35);\n  border-radius: 999px;\n  white-space: nowrap;\n  flex-shrink: 0;\n}\n\n/* ==========================================================================\n   Chapter 04: AI 工具与五步制作流程\n   ========================================================================== */\n\n.workflow-layout {\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n@media (min-width: 860px) {\n  .workflow-layout {\n    display: grid;\n    grid-template-columns: 0.88fr 1.12fr;\n    gap: 44px;\n    align-items: start;\n  }\n\n  .workflow-layout__side {\n    position: sticky;\n    top: 84px;\n  }\n\n  .workflow-steps-lead {\n    margin-top: 6px;\n  }\n}\n\n.codex-colophon {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  margin: 18px 0 6px;\n  padding: 15px 16px;\n  background-color: var(--paper-ivory);\n  border: 1.2px solid var(--ink);\n  border-radius: 6px 3px 8px 4px;\n  box-shadow: 3px 4px 0 var(--terracotta-wash);\n}\n\n.codex-colophon__seal {\n  width: 54px;\n  height: 54px;\n  flex-shrink: 0;\n}\n\n.codex-colophon__seal svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.codex-colophon__label {\n  font-size: 12px;\n  letter-spacing: 0.05em;\n  color: var(--ink-muted);\n  display: block;\n}\n\n.codex-colophon__title {\n  margin: 2px 0 3px;\n  font-family: var(--font-serif-cn);\n  font-size: 16.5px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.codex-colophon__desc {\n  margin: 0;\n  font-size: 13.8px;\n  line-height: 1.65;\n  color: var(--ink-soft);\n}\n\n.workflow-steps-lead {\n  margin-bottom: 16px;\n}\n\n.workflow-trail {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  position: relative;\n}\n\n.workflow-step {\n  position: relative;\n  padding-left: 42px;\n  padding-bottom: 22px;\n}\n\n.workflow-step:last-child {\n  padding-bottom: 0;\n}\n\n.workflow-step:not(:last-child)::before {\n  content: \"\";\n  position: absolute;\n  left: 13px;\n  top: 30px;\n  bottom: 2px;\n  border-left: 1.5px dashed rgba(39, 35, 31, 0.30);\n}\n\n.workflow-step__marker {\n  position: absolute;\n  left: 0;\n  top: 2px;\n  width: 28px;\n  height: 28px;\n  border-radius: 54% 46% 48% 52% / 47% 53% 46% 54%;\n  border: 1.3px solid var(--ink);\n  background-color: var(--paper-ivory);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--font-display-num);\n  font-weight: 700;\n  font-size: 15px;\n  color: var(--ink);\n}\n\n.workflow-step:nth-child(1) .workflow-step__marker { background-color: var(--ochre-wash); }\n.workflow-step:nth-child(2) .workflow-step__marker { background-color: var(--terracotta-wash); }\n.workflow-step:nth-child(3) .workflow-step__marker { background-color: var(--cobalt-wash); }\n.workflow-step:nth-child(4) .workflow-step__marker { background-color: var(--sage-wash); }\n.workflow-step:nth-child(5) .workflow-step__marker { background-color: var(--ochre-wash); }\n\n.workflow-step__title {\n  margin: 0 0 4px;\n  font-family: var(--font-serif-cn);\n  font-size: 16.5px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.workflow-step__desc {\n  margin: 0;\n  font-size: 14.8px;\n  line-height: 1.78;\n  color: var(--ink-soft);\n  text-wrap: pretty;\n}\n\n/* ==========================================================================\n   Chapter 05: 周期与分工 · 撕页日历 & 双栏协作角色卡\n   ========================================================================== */\n\n@media (min-width: 860px) {\n  .team-top-row {\n    display: grid;\n    grid-template-columns: 0.9fr 1.1fr;\n    gap: 32px;\n    align-items: center;\n    margin-bottom: 24px;\n  }\n\n  .team-top-row .chapter-header {\n    margin-bottom: 0;\n  }\n\n  .team-top-row .calendar-row {\n    margin: 0;\n  }\n}\n\n.calendar-row {\n  display: grid;\n  grid-template-columns: 112px 1fr;\n  gap: 14px;\n  align-items: center;\n  margin: 18px 0 22px;\n  padding: 15px;\n  background-color: var(--paper-ivory);\n  border: 1.2px solid var(--ink);\n  border-radius: 5px 8px 4px 7px;\n}\n\n.eph-leaf {\n  background-color: var(--paper);\n  border: 1.2px solid var(--ink);\n  border-radius: 3px 3px 6px 6px;\n  text-align: center;\n  overflow: hidden;\n  box-shadow: 2px 3px 0 var(--terracotta-wash);\n}\n\n.eph-leaf__top {\n  background-color: var(--terracotta);\n  color: var(--paper-ivory);\n  font-size: 11.5px;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  padding: 4px 6px;\n}\n\n.eph-leaf__day {\n  font-family: var(--font-display-num);\n  font-weight: 700;\n  font-size: 28px;\n  line-height: 1.15;\n  color: var(--ink);\n  padding-top: 5px;\n}\n\n.eph-leaf__sub {\n  font-size: 11.5px;\n  color: var(--ink-soft);\n  padding: 2px 4px 7px;\n}\n\n.calendar-summary__big {\n  margin: 0 0 4px;\n  font-family: var(--font-serif-cn);\n  font-size: 17.5px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.calendar-summary__note {\n  margin: 0;\n  font-size: 14px;\n  line-height: 1.68;\n  color: var(--ink-soft);\n}\n\n.team-dossier {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  margin: 18px 0;\n}\n\n@media (min-width: 768px) {\n  .team-dossier {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 20px;\n  }\n}\n\n.role-card {\n  padding: 18px 18px 16px;\n  background-color: var(--paper-ivory);\n  border: 1px solid var(--rule-strong);\n  border-radius: 4px 9px 5px 7px;\n}\n\n.role-card--lead {\n  border-color: var(--ink);\n  box-shadow: 3px 4px 0 var(--ochre-wash);\n}\n\n.role-card--dev {\n  box-shadow: 3px 4px 0 var(--cobalt-wash);\n}\n\n.role-card__eyebrow {\n  font-size: 12px;\n  color: var(--terracotta);\n  font-weight: 600;\n  letter-spacing: 0.05em;\n}\n\n.role-card--dev .role-card__eyebrow {\n  color: var(--cobalt);\n}\n\n.role-card__name {\n  margin: 3px 0 8px;\n  font-family: var(--font-serif-cn);\n  font-size: 18px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.duty-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 10px;\n}\n\n.duty-tag {\n  font-size: 12.8px;\n  line-height: 1.4;\n  padding: 4px 9px;\n  border-radius: 3px 6px 4px 5px;\n  background-color: var(--paper-tint-ochre);\n  border: 1px solid rgba(39, 35, 31, 0.16);\n  color: var(--ink);\n}\n\n.role-card--dev .duty-tag {\n  background-color: var(--paper-tint-blue);\n}\n\n/* ==========================================================================\n   Chapter 06: 结果与教师原话明信片\n   ========================================================================== */\n\n.outcome-layout {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n@media (min-width: 860px) {\n  .outcome-layout {\n    display: grid;\n    grid-template-columns: 0.92fr 1.08fr;\n    gap: 40px;\n    align-items: start;\n  }\n\n  .outcome-layout__quote {\n    position: sticky;\n    top: 84px;\n  }\n}\n\n.postcard-quote {\n  position: relative;\n  margin: 18px 2px 18px;\n  padding: 22px 20px 20px;\n  background-color: #FDFBF5;\n  background-image: repeating-linear-gradient(\n    to bottom,\n    transparent 0px,\n    transparent 31px,\n    rgba(51, 88, 138, 0.11) 32px\n  );\n  border: 1.3px solid var(--ink);\n  border-radius: 4px 6px 5px 4px;\n  transform: rotate(-0.6deg);\n  box-shadow: 4px 6px 0 rgba(39, 35, 31, 0.10);\n}\n\n.postcard-quote__header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  margin-bottom: 12px;\n}\n\n.postcard-quote__label {\n  font-family: var(--font-serif-cn);\n  font-size: 12.5px;\n  letter-spacing: 0.05em;\n  color: var(--ink-muted);\n  border-bottom: 1px solid var(--rule-strong);\n  padding-bottom: 3px;\n}\n\n.postcard-quote__stamp {\n  width: 44px;\n  height: 50px;\n  flex-shrink: 0;\n  margin-top: -4px;\n}\n\n.postcard-quote__stamp svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.postcard-quote__text {\n  margin: 0;\n  font-family: var(--font-serif-cn);\n  font-size: 17.5px;\n  font-weight: 600;\n  line-height: 1.85;\n  color: var(--ink);\n  position: relative;\n}\n\n.postcard-quote__mark {\n  font-family: var(--font-display-num);\n  font-size: 38px;\n  line-height: 0;\n  vertical-align: -10px;\n  color: var(--terracotta);\n  margin-right: 4px;\n}\n\n.postcard-quote__footer {\n  margin-top: 14px;\n  text-align: right;\n  font-size: 13px;\n  color: var(--ink-soft);\n  font-family: var(--font-serif-cn);\n}\n\n/* 5 Concrete Results List */\n.outcome-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.outcome-card {\n  padding: 15px 16px;\n  background-color: var(--paper-ivory);\n  border: 1px solid var(--rule-strong);\n  border-radius: 5px 8px 4px 6px;\n  display: grid;\n  grid-template-columns: 32px 1fr;\n  gap: 10px;\n  align-items: start;\n}\n\n.outcome-card__check {\n  width: 28px;\n  height: 28px;\n  margin-top: 2px;\n}\n\n.outcome-card__check svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.outcome-card__title {\n  margin: 0 0 4px;\n  font-family: var(--font-serif-cn);\n  font-size: 16.5px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.outcome-card__desc {\n  margin: 0;\n  font-size: 14.8px;\n  line-height: 1.76;\n  color: var(--ink-soft);\n  text-wrap: pretty;\n}\n\n/* ==========================================================================\n   Colophon Footer\n   ========================================================================== */\n\n.colophon-footer {\n  padding: 30px var(--gutter) 16px;\n  text-align: center;\n  border-top: 1.5px solid var(--ink);\n  position: relative;\n}\n\n.colophon-footer::before {\n  content: \"\";\n  position: absolute;\n  top: 3px;\n  left: 0;\n  right: 0;\n  border-top: 0.75px solid var(--rule-strong);\n}\n\n.colophon-ornament {\n  width: 96px;\n  height: 36px;\n  margin: 0 auto 10px;\n}\n\n.colophon-ornament svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.colophon-title {\n  margin: 0 0 4px;\n  font-family: var(--font-serif-cn);\n  font-size: 14px;\n  font-weight: 700;\n  color: var(--ink);\n}\n\n.colophon-meta {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.7;\n  color: var(--ink-muted);\n}\n\n  </style>\n</head>\n<body>\n  <!-- Reading Progress Hairline -->\n  <div class=\"reading-progress\" aria-hidden=\"true\">\n    <div class=\"reading-progress__bar\" id=\"readingBar\"></div>\n  </div>\n\n  <!-- Subtle Cotton Paper Grain -->\n  <div class=\"paper-grain\" aria-hidden=\"true\"></div>\n\n  <!-- Shared SVG Filters for Hand-Inked Nib & Offset Gouache Edges -->\n  <svg class=\"svg-defs-vault\" aria-hidden=\"true\" xmlns=\"http://www.w3.org/2000/svg\">\n    <defs>\n      <filter id=\"ink-nib\" x=\"-8%\" y=\"-8%\" width=\"116%\" height=\"116%\">\n        <feTurbulence type=\"fractalNoise\" baseFrequency=\"0.045\" numOctaves=\"3\" seed=\"7\" result=\"noise\" />\n        <feDisplacementMap in=\"SourceGraphic\" in2=\"noise\" scale=\"1.35\" xChannelSelector=\"R\" yChannelSelector=\"G\" />\n      </filter>\n      <filter id=\"gouache-edge\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n        <feTurbulence type=\"fractalNoise\" baseFrequency=\"0.03\" numOctaves=\"2\" seed=\"12\" result=\"gnoise\" />\n        <feDisplacementMap in=\"SourceGraphic\" in2=\"gnoise\" scale=\"2.6\" xChannelSelector=\"R\" yChannelSelector=\"G\" />\n      </filter>\n    </defs>\n  </svg>\n\n  <main class=\"carnet-sheet\">\n    <!-- ====================================================================\n         封面与总标题 (Responsive Two-Column Spread on Web, Stack on Mobile)\n         ==================================================================== -->\n    <header class=\"cover\" id=\"top\">\n      <div class=\"masthead-bar\">\n        <span class=\"masthead-brand\">\n          <span class=\"masthead-dot\" aria-hidden=\"true\"></span>\n          灯下白 · FDE 案例展示\n        </span>\n        <span class=\"masthead-folio\">案例档案 01 · 2026</span>\n      </div>\n\n      <div class=\"cover-spread\">\n        <!-- Illustration Column (First on Mobile, Right Plate on Desktop) -->\n        <figure class=\"cover-illustration\" aria-label=\"手绘水粉插画：台灯暖光下的分层互动绘本与南国绿植窗台\">\n          <svg viewBox=\"0 0 380 236\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <!-- Soft Warm Pool of Lamp Light (\"灯下白\") -->\n            <path d=\"M118 82 L42 204 C98 220 228 220 278 202 L182 82 Z\"\n                  fill=\"#FDF9EE\" opacity=\"0.92\" filter=\"url(#gouache-edge)\" />\n            <ellipse cx=\"164\" cy=\"202\" rx=\"118\" ry=\"18\"\n                     fill=\"#F7E5B4\" opacity=\"0.65\" style=\"mix-blend-mode:multiply\" filter=\"url(#gouache-edge)\" />\n\n            <!-- Right Background: Southern Arched Window & Sky Wash -->\n            <g style=\"mix-blend-mode:multiply\" filter=\"url(#gouache-edge)\">\n              <path d=\"M266 36 C266 16 336 16 336 36 L336 138 L266 138 Z\" fill=\"#DCE7F3\" />\n              <circle cx=\"312\" cy=\"48\" r=\"13\" fill=\"#F3C567\" opacity=\"0.85\" />\n              <!-- Terracotta Plant Pot Gouache -->\n              <path d=\"M286 142 L322 142 L316 174 L292 174 Z\" fill=\"#DDA08E\" />\n              <!-- Olive / Banyan Leaves Gouache -->\n              <path d=\"M303 140 C285 124 274 106 283 96 C293 98 302 114 304 134 Z\" fill=\"#B9CFB4\" />\n              <path d=\"M306 138 C316 114 332 100 342 106 C340 120 324 132 308 140 Z\" fill=\"#9BB996\" />\n              <path d=\"M304 128 C298 104 304 82 315 82 C322 94 316 114 306 130 Z\" fill=\"#B9CFB4\" />\n            </g>\n\n            <!-- Left-Center Gouache Fills (Offset Print Style) -->\n            <g transform=\"translate(3, 3)\" style=\"mix-blend-mode:multiply\" filter=\"url(#gouache-edge)\">\n              <!-- Pleated Terracotta Lampshade Fill -->\n              <path d=\"M114 44 L174 44 L192 84 L96 84 Z\" fill=\"#E39A86\" />\n              <!-- Cobalt Ceramic Lamp Base Fill -->\n              <path d=\"M84 156 C72 164 70 184 82 194 L118 194 C128 184 126 164 114 156 Z\" fill=\"#9BB4D4\" />\n              <!-- Open Custom Course Workbook Fill -->\n              <path d=\"M132 174 C156 166 184 168 204 176 C224 168 252 166 276 174 L286 204 C258 198 226 198 204 206 C182 198 150 198 122 204 Z\"\n                    fill=\"#FCF8EF\" />\n              <!-- Three A / B / C Tab Ribbons protruding from book -->\n              <rect x=\"218\" y=\"156\" width=\"15\" height=\"18\" rx=\"2\" transform=\"rotate(-6 218 156)\" fill=\"#F0C362\" />\n              <rect x=\"238\" y=\"154\" width=\"15\" height=\"19\" rx=\"2\" transform=\"rotate(2 238 154)\" fill=\"#96B3D6\" />\n              <rect x=\"258\" y=\"157\" width=\"15\" height=\"18\" rx=\"2\" transform=\"rotate(9 258 157)\" fill=\"#A6C4A1\" />\n              <!-- Little Paper Bird Rising -->\n              <path d=\"M212 118 L232 108 L224 126 L238 122 L216 134 Z\" fill=\"#9BB4D4\" />\n            </g>\n\n            <!-- Hand-Inked Charcoal Line Art -->\n            <g stroke=\"#27231F\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n              <!-- Horizon Desk Line -->\n              <path d=\"M22 196 C112 194 268 195 358 196\" stroke-width=\"1.5\" />\n\n              <!-- Arched Window Frame -->\n              <path d=\"M263 138 L263 38 C263 13 335 13 335 38 L335 138\" stroke-width=\"1.4\" />\n              <path d=\"M255 139 L344 139\" stroke-width=\"1.6\" />\n              <path d=\"M299 20 L299 138\" stroke-width=\"1\" stroke-dasharray=\"2 3\" opacity=\"0.55\" />\n              <path d=\"M264 84 L334 84\" stroke-width=\"1\" opacity=\"0.55\" />\n\n              <!-- Potted Southern Plant Ink -->\n              <path d=\"M284 140 L320 140 L314 173 L290 173 Z\" stroke-width=\"1.4\" />\n              <path d=\"M281 140 L323 140\" stroke-width=\"1.8\" />\n              <path d=\"M302 140 C286 125 274 108 282 95 C293 98 301 114 303 136\" stroke-width=\"1.35\" />\n              <path d=\"M304 138 C315 116 330 101 341 105 C338 119 322 131 305 139\" stroke-width=\"1.35\" />\n              <path d=\"M302 130 C297 106 303 82 314 81 C320 93 314 113 304 132\" stroke-width=\"1.35\" />\n\n              <!-- Brass & Ceramic Desk Lamp -->\n              <path d=\"M141 42 C141 35 147 35 147 42\" stroke-width=\"1.5\" />\n              <path d=\"M112 43 L172 43 L190 83 L94 83 Z\" stroke-width=\"1.65\" />\n              <path d=\"M126 44 L115 82 M142 44 L142 82 M158 44 L169 82\" stroke-width=\"1.05\" opacity=\"0.65\" />\n              <path d=\"M97 78 C126 81 158 81 187 78\" stroke-width=\"1\" />\n              <path d=\"M136 84 C137 92 147 92 148 84\" stroke-width=\"1.4\" fill=\"#F8DE7E\" />\n              <path d=\"M126 96 L118 106 M142 98 L142 110 M158 96 L166 106\" stroke-width=\"1.2\" stroke=\"#C25941\" />\n              <path d=\"M114 83 C92 98 88 128 98 155\" stroke-width=\"2.1\" />\n              <path d=\"M119 83 C98 98 94 128 103 155\" stroke-width=\"1.1\" opacity=\"0.65\" />\n              <path d=\"M83 155 L115 155 C126 165 127 183 117 195 L81 195 C71 183 72 165 83 155 Z\" stroke-width=\"1.6\" />\n              <path d=\"M80 176 L88 176 M82 182 L92 182 M85 188 L95 188\" stroke-width=\"1\" opacity=\"0.5\" />\n\n              <!-- Open Illustrated Workbook & A/B/C Tabs -->\n              <path d=\"M130 173 C154 165 182 167 202 176 C222 167 250 165 274 173 L284 203 C256 197 224 197 202 206 C180 197 148 197 120 203 Z\"\n                    stroke-width=\"1.6\" fill=\"#FCF9F2\" />\n              <path d=\"M202 176 L202 206\" stroke-width=\"1.4\" />\n              <rect x=\"144\" y=\"178\" width=\"24\" height=\"14\" rx=\"2\" stroke-width=\"1.1\" fill=\"#F7E7BE\" />\n              <path d=\"M174 180 L191 180 M174 186 L188 186 M144 196 L186 196\" stroke-width=\"1.1\" opacity=\"0.7\" />\n              <circle cx=\"224\" cy=\"184\" r=\"6.5\" stroke-width=\"1.1\" fill=\"#F2DAD2\" />\n              <path d=\"M236 181 L262 181 M236 187 L258 187 M216 195 L264 195\" stroke-width=\"1.1\" opacity=\"0.7\" />\n\n              <!-- A / B / C Bookmarks -->\n              <path d=\"M216 168 L215 154 L230 153 L231 167\" stroke-width=\"1.25\" />\n              <path d=\"M237 167 L238 152 L252 153 L251 167\" stroke-width=\"1.25\" />\n              <path d=\"M257 168 L260 154 L274 157 L270 171\" stroke-width=\"1.25\" />\n\n              <!-- Paper Bird & Dotted Flight Path -->\n              <path d=\"M203 162 C196 146 200 132 210 124\" stroke-width=\"1.1\" stroke-dasharray=\"2.5 3.5\" opacity=\"0.65\" />\n              <path d=\"M209 119 L232 107 L223 126 L210 119 Z\" stroke-width=\"1.3\" />\n              <path d=\"M223 126 L237 121 L216 133 L223 126 Z\" stroke-width=\"1.3\" />\n            </g>\n\n            <!-- Hand-Lettered A / B / C on Tabs -->\n            <text x=\"220\" y=\"164\" font-family=\"Georgia, serif\" font-size=\"9.5\" font-weight=\"700\" fill=\"#27231F\">A</text>\n            <text x=\"241\" y=\"163\" font-family=\"Georgia, serif\" font-size=\"9.5\" font-weight=\"700\" fill=\"#27231F\">B</text>\n            <text x=\"261\" y=\"166\" font-family=\"Georgia, serif\" font-size=\"9.5\" font-weight=\"700\" fill=\"#27231F\">C</text>\n          </svg>\n        </figure>\n\n        <!-- Copy Column -->\n        <div class=\"cover-copy\">\n          <div class=\"cover-kicker\">\n            <span>特殊教育数字化 · 定制交付手记</span>\n          </div>\n\n          <h1 class=\"cover-title\">\n            <span class=\"cover-title__eyebrow\">灯下白FDE案例展示——</span>\n            <span class=\"cover-title__sub\">南方康复学校<br />脑瘫儿童课程定制项目</span>\n          </h1>\n\n          <!-- Hand-drawn terracotta brush wave under title -->\n          <svg class=\"cover-brush-underline\" viewBox=\"0 0 180 12\" fill=\"none\" aria-hidden=\"true\">\n            <path d=\"M3 7 C42 2, 88 11, 134 5 C152 3, 166 6, 177 5\"\n                  stroke=\"#C25941\" stroke-width=\"3\" stroke-linecap=\"round\" filter=\"url(#ink-nib)\" />\n          </svg>\n\n          <p class=\"cover-lead\">\n            当通用数字课件遇上能力各异的特殊教育课堂，如何让技术退到幕后，做成一位老师随手能开、十五个孩子各自好用的生活互动课？这是一份来自真实交付现场的项目手记。\n          </p>\n\n          <div class=\"cover-meta-row\" aria-label=\"项目关键速览\">\n            <div class=\"meta-cell\">\n              <span class=\"meta-cell__label\">直接服务规模</span>\n              <span class=\"meta-cell__val\">1 师 · 15 生</span>\n            </div>\n            <div class=\"meta-cell\">\n              <span class=\"meta-cell__label\">约定交付体量</span>\n              <span class=\"meta-cell__val\">10 节 × A/B/C</span>\n            </div>\n            <div class=\"meta-cell\">\n              <span class=\"meta-cell__label\">项目实施周期</span>\n              <span class=\"meta-cell__val\">约 35 天</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <!-- Sticky Chapter Ribbon (Concise on Mobile, Full Titles on Desktop Web) -->\n    <nav class=\"chapter-nav\" aria-label=\"案例章节导航\">\n      <ul class=\"chapter-nav__list\">\n        <li><a class=\"chapter-nav__link is-active\" href=\"#sec-client\"><span class=\"chapter-nav__num\">01</span>甲方<span class=\"nav-extra\">规模</span></a></li>\n        <li><a class=\"chapter-nav__link\" href=\"#sec-problem\"><span class=\"chapter-nav__num\">02</span><span class=\"nav-extra\">面临</span>难题</a></li>\n        <li><a class=\"chapter-nav__link\" href=\"#sec-delivery\"><span class=\"chapter-nav__num\">03</span>交付<span class=\"nav-extra\">内容</span></a></li>\n        <li><a class=\"chapter-nav__link\" href=\"#sec-workflow\"><span class=\"chapter-nav__num\">04</span><span class=\"nav-extra\">工具与</span>流程</a></li>\n        <li><a class=\"chapter-nav__link\" href=\"#sec-team\"><span class=\"chapter-nav__num\">05</span><span class=\"nav-extra\">周期与</span>分工</a></li>\n        <li><a class=\"chapter-nav__link\" href=\"#sec-outcome\"><span class=\"chapter-nav__num\">06</span><span class=\"nav-extra\">项目</span>成果</a></li>\n      </ul>\n    </nav>\n\n    <!-- ====================================================================\n         CHAPTER 01 · 甲方：学校名称与规模\n         ==================================================================== -->\n    <section class=\"chapter\" id=\"sec-client\">\n      <div class=\"client-layout\">\n        <div class=\"client-layout__text\">\n          <div class=\"chapter-header\">\n            <div class=\"chapter-rubric\">\n              <span class=\"chapter-num-badge\">01</span>\n              <span class=\"chapter-sub-cn\">服务对象与教学规模</span>\n            </div>\n            <h2 class=\"chapter-title\">甲方：学校名称与规模</h2>\n          </div>\n\n          <p class=\"prose-p\">\n            项目甲方为<span class=\"gouache-hl\">南方某康复学校</span>。本次项目直接服务的教学规模为 <strong style=\"color:var(--ink)\">1 名教师、15 名学生</strong>。\n          </p>\n\n          <p class=\"prose-p\">\n            项目面向有<span class=\"gouache-hl--rose\">特殊教育和脑瘫康复需求</span>的儿童，课程需要充分考虑学生之间的能力差异，以及教师实际使用数字化教学资源的便利性。\n          </p>\n        </div>\n\n        <!-- Bespoke Pochoir Illustration: 1 Guiding Lantern / Teacher & Exactly 15 Unique Paper Boats -->\n        <div class=\"classroom-sketch-card\">\n          <svg viewBox=\"0 0 348 118\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"一位教师引航与十五只大小颜色各异的小纸船插画，寓意因材施教\">\n            <!-- Gentle Water / Breeze Waves -->\n            <path d=\"M12 56 C78 48, 146 64, 214 54 C268 46, 306 58, 338 52\" stroke=\"#33588A\" stroke-opacity=\"0.22\" stroke-width=\"1.3\" stroke-dasharray=\"4 4\" />\n            <path d=\"M18 96 C92 88, 168 102, 244 92 C288 86, 316 96, 338 92\" stroke=\"#33588A\" stroke-opacity=\"0.22\" stroke-width=\"1.3\" stroke-dasharray=\"4 4\" />\n\n            <!-- Left: 1 Teacher's Warm Lighthouse / Open Book Beacon -->\n            <g transform=\"translate(2,2)\" style=\"mix-blend-mode:multiply\" filter=\"url(#gouache-edge)\">\n              <circle cx=\"38\" cy=\"58\" r=\"24\" fill=\"#F7E5B4\" />\n              <path d=\"M26 78 L50 78 L46 46 L30 46 Z\" fill=\"#E59C88\" />\n            </g>\n            <g stroke=\"#27231F\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n              <path d=\"M25 80 L51 80 L46 45 L30 45 Z\" />\n              <path d=\"M28 45 L38 33 L48 45 Z\" fill=\"#C25941\" />\n              <circle cx=\"38\" cy=\"56\" r=\"4.5\" fill=\"#F9E395\" />\n              <path d=\"M56 48 L65 44 M58 56 L68 56 M56 64 L65 68\" stroke=\"#C25941\" stroke-width=\"1.3\" />\n            </g>\n\n            <!-- Right: Exactly 15 Unique Little Paper Boats (8 top row + 7 bottom row = 15 students!) -->\n            <g filter=\"url(#ink-nib)\" stroke=\"#27231F\" stroke-width=\"1.15\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <!-- Row 1 (8 boats) -->\n              <g transform=\"translate(82, 34)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#D8E4F2\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#96B3D6\"/></g>\n              <g transform=\"translate(114, 28) scale(1.12)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#F7E7BE\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#E8B95B\"/></g>\n              <g transform=\"translate(150, 36) scale(0.9)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#F2DAD2\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#DE8F79\"/></g>\n              <g transform=\"translate(180, 30) scale(1.05)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#DCE9DA\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#98B894\"/></g>\n              <g transform=\"translate(214, 35) scale(0.95)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#F7E7BE\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#E8B95B\"/></g>\n              <g transform=\"translate(246, 27) scale(1.1)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#D8E4F2\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#96B3D6\"/></g>\n              <g transform=\"translate(282, 34) scale(0.88)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#DCE9DA\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#98B894\"/></g>\n              <g transform=\"translate(312, 29) scale(1.02)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#F2DAD2\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#DE8F79\"/></g>\n\n              <!-- Row 2 (7 boats = total 15) -->\n              <g transform=\"translate(94, 72) scale(1.04)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#DCE9DA\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#98B894\"/></g>\n              <g transform=\"translate(130, 76) scale(0.92)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#D8E4F2\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#96B3D6\"/></g>\n              <g transform=\"translate(164, 70) scale(1.14)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#F2DAD2\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#DE8F79\"/></g>\n              <g transform=\"translate(202, 75) scale(0.95)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#F7E7BE\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#E8B95B\"/></g>\n              <g transform=\"translate(236, 71) scale(1.06)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#DCE9DA\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#98B894\"/></g>\n              <g transform=\"translate(272, 76) scale(0.9)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#F7E7BE\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#E8B95B\"/></g>\n              <g transform=\"translate(304, 71) scale(1.05)\"><polygon points=\"0,14 10,2 20,14\" fill=\"#D8E4F2\"/><polygon points=\"2,14 18,14 15,19 5,19\" fill=\"#96B3D6\"/></g>\n            </g>\n          </svg>\n\n          <div class=\"scale-stats\">\n            <div>\n              <div class=\"scale-stat\">\n                <span class=\"scale-stat__num\">1</span>\n                <span class=\"scale-stat__unit\">名直接授课教师</span>\n              </div>\n              <span class=\"scale-stat__desc\">课件需好打开、易操作、方便反复使用</span>\n            </div>\n            <div class=\"scale-stat--students\">\n              <div class=\"scale-stat\">\n                <span class=\"scale-stat__num\">15</span>\n                <span class=\"scale-stat__unit\">名特教与康复儿童</span>\n              </div>\n              <span class=\"scale-stat__desc\">兼顾脑瘫康复需求与显著个体能力差异</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- Torn Paper / Hand-drawn Wave Divider -->\n    <div class=\"deckle-divider\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 490 14\" preserveAspectRatio=\"none\">\n        <path d=\"M0 14 L0 6 Q24 2 48 7 T96 6 T144 7 T192 5 T240 7 T288 6 T336 7 T384 5 T432 7 T490 6 L490 14 Z\" fill=\"#EFE7D6\" />\n      </svg>\n    </div>\n\n    <!-- ====================================================================\n         CHAPTER 02 · 难题：学校原来面临什么问题？\n         ==================================================================== -->\n    <section class=\"chapter chapter--tinted-warm\" id=\"sec-problem\">\n      <div class=\"problem-top-grid\">\n        <div>\n          <div class=\"chapter-header\">\n            <div class=\"chapter-rubric\">\n              <span class=\"chapter-num-badge chapter-num-badge--blue\">02</span>\n              <span class=\"chapter-sub-cn\">特殊教育场景下的四项痛点</span>\n            </div>\n            <h2 class=\"chapter-title\">难题：学校原来面临什么问题？</h2>\n          </div>\n\n          <div class=\"contrast-banner\">\n            <p class=\"contrast-banner__lead\">\n              这个项目最核心的挑战，是如何让数字化课程<strong>真正适应特殊教育场景</strong>。\n            </p>\n          </div>\n        </div>\n\n        <div class=\"problem-top-grid__prose\">\n          <p class=\"prose-p\">\n            普通数字课程通常采用统一的教学难度和交互方式，但特殊教育学生在<span class=\"gouache-hl\">认知、理解、操作及表达能力</span>方面存在明显差异。同样一节课，不同学生可能需要完全不同的教学支持。\n          </p>\n          <p class=\"prose-p\">因此，项目需要解决以下四个具体问题：</p>\n        </div>\n      </div>\n\n      <ol class=\"problem-ledger\">\n        <!-- Problem 1 -->\n        <li class=\"problem-item\">\n          <div class=\"problem-item__illus\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\">\n              <rect x=\"7\" y=\"22\" width=\"12\" height=\"19\" rx=\"2\" fill=\"#F7E7BE\" transform=\"translate(2,2)\" />\n              <rect x=\"19\" y=\"15\" width=\"12\" height=\"26\" rx=\"2\" fill=\"#D8E4F2\" transform=\"translate(2,2)\" />\n              <rect x=\"31\" y=\"8\" width=\"12\" height=\"33\" rx=\"2\" fill=\"#DCE9DA\" transform=\"translate(2,2)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.35\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <rect x=\"7\" y=\"22\" width=\"11\" height=\"19\" rx=\"1.5\" />\n                <rect x=\"19\" y=\"15\" width=\"11\" height=\"26\" rx=\"1.5\" />\n                <rect x=\"31\" y=\"8\" width=\"11\" height=\"33\" rx=\"1.5\" />\n              </g>\n              <text x=\"10\" y=\"35\" font-family=\"Georgia,serif\" font-size=\"9\" font-weight=\"700\" fill=\"#27231F\">A</text>\n              <text x=\"22\" y=\"31\" font-family=\"Georgia,serif\" font-size=\"9\" font-weight=\"700\" fill=\"#27231F\">B</text>\n              <text x=\"34\" y=\"27\" font-family=\"Georgia,serif\" font-size=\"9\" font-weight=\"700\" fill=\"#27231F\">C</text>\n            </svg>\n          </div>\n          <div>\n            <div class=\"problem-item__head\">\n              <span class=\"problem-item__idx\">01.</span>\n              <h3 class=\"problem-item__title\">教学难度分层</h3>\n            </div>\n            <p class=\"problem-item__desc\">同一教学主题需要提供 A、B、C 三个难度版本，以适应不同能力水平的学生。</p>\n          </div>\n        </li>\n\n        <!-- Problem 2 -->\n        <li class=\"problem-item\">\n          <div class=\"problem-item__illus\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\">\n              <circle cx=\"20\" cy=\"22\" r=\"12\" fill=\"#F2DAD2\" />\n              <circle cx=\"31\" cy=\"28\" r=\"10\" fill=\"#D8E4F2\" style=\"mix-blend-mode:multiply\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.35\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <path d=\"M11 16 L24 16 M11 21 L20 21\" />\n                <path d=\"M29 14 L29 29 C29 32 25 33 24 31 C23 29 26 27 29 28\" />\n                <path d=\"M29 14 L36 12 L36 17 L29 19\" fill=\"#C25941\" />\n                <polygon points=\"14,29 23,34 14,39\" fill=\"#F7E7BE\" />\n              </g>\n            </svg>\n          </div>\n          <div>\n            <div class=\"problem-item__head\">\n              <span class=\"problem-item__idx\">02.</span>\n              <h3 class=\"problem-item__title\">教学内容多模态呈现</h3>\n            </div>\n            <p class=\"problem-item__desc\">课程需要结合文字、音频、视频、互动等形式，让学生能够通过不同方式理解内容。</p>\n          </div>\n        </li>\n\n        <!-- Problem 3 -->\n        <li class=\"problem-item\">\n          <div class=\"problem-item__illus\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\">\n              <rect x=\"9\" y=\"11\" width=\"30\" height=\"24\" rx=\"3\" fill=\"#F7E7BE\" transform=\"translate(2,2)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.35\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <rect x=\"8\" y=\"10\" width=\"30\" height=\"24\" rx=\"3\" fill=\"#FCF9F2\" />\n                <path d=\"M8 17 L38 17\" />\n                <circle cx=\"13\" cy=\"13.5\" r=\"1\" fill=\"#27231F\" />\n                <circle cx=\"17\" cy=\"13.5\" r=\"1\" fill=\"#27231F\" />\n                <polygon points=\"20,21 28,25.5 20,30\" fill=\"#E39A86\" />\n                <path d=\"M28 31 L34 40 M28 31 L30 39 M28 31 L36 34\" />\n              </g>\n            </svg>\n          </div>\n          <div>\n            <div class=\"problem-item__head\">\n              <span class=\"problem-item__idx\">03.</span>\n              <h3 class=\"problem-item__title\">降低教师使用门槛</h3>\n            </div>\n            <p class=\"problem-item__desc\">只有一名教师直接参与教学，课程需要尽可能方便打开、操作和重复使用。</p>\n          </div>\n        </li>\n\n        <!-- Problem 4 -->\n        <li class=\"problem-item\">\n          <div class=\"problem-item__illus\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\">\n              <path d=\"M10 17 L21 17 L24 21 L40 21 L40 38 L10 38 Z\" fill=\"#DCE9DA\" transform=\"translate(2,2)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.35\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <path d=\"M9 16 L20 16 L23 20 L39 20 L39 37 L9 37 Z\" fill=\"#FCF9F2\" />\n                <path d=\"M19 29 L23 33 L30 25\" stroke=\"#557653\" stroke-width=\"1.8\" />\n              </g>\n            </svg>\n          </div>\n          <div>\n            <div class=\"problem-item__head\">\n              <span class=\"problem-item__idx\">04.</span>\n              <h3 class=\"problem-item__title\">适应学校实际设备环境</h3>\n            </div>\n            <p class=\"problem-item__desc\">课程需要支持本地离线运行，减少对网络连接及额外软件安装的依赖。</p>\n          </div>\n        </li>\n      </ol>\n    </section>\n\n    <div class=\"deckle-divider\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 490 14\" preserveAspectRatio=\"none\" style=\"background:#EFE7D6\">\n        <path d=\"M0 14 L0 6 Q24 11 48 6 T96 7 T144 5 T192 7 T240 5 T288 7 T336 6 T384 8 T432 6 T490 7 L490 14 Z\" fill=\"#F7F2E7\" />\n      </svg>\n    </div>\n\n    <!-- ====================================================================\n         CHAPTER 03 · 交付内容：做了什么？\n         ==================================================================== -->\n    <section class=\"chapter\" id=\"sec-delivery\">\n      <div class=\"chapter-header\">\n        <div class=\"chapter-rubric\">\n          <span class=\"chapter-num-badge chapter-num-badge--ochre\">03</span>\n          <span class=\"chapter-sub-cn\">分层多模态与本地化交付</span>\n        </div>\n        <h2 class=\"chapter-title\">交付内容：做了什么？</h2>\n      </div>\n\n      <p class=\"prose-p delivery-lead\">\n        项目约定交付 <span class=\"gouache-hl\">10 节数字化互动课程</span>，每节均设计 <strong style=\"color:var(--ink)\">A、B、C 三个难度层级</strong>，最终采用<span class=\"gouache-hl--blue\">本地 HTML 形式</span>交付。\n      </p>\n\n      <!-- Responsive Two-Column Row on Web: Left = A/B/C Switcher, Right = Local HTML Memo -->\n      <div class=\"delivery-feature-split\">\n        <!-- Interactive Tactile Folder Switcher: A / B / C Difficulty Layers -->\n        <div class=\"tier-showcase\" aria-label=\"A/B/C三档难度分层切换卡片\">\n          <div class=\"tier-showcase__caption\">\n            <span>同课异构 · 三档分层设计结构</span>\n            <span>点击标签翻阅 ▾</span>\n          </div>\n          <div class=\"tier-tabs\" role=\"tablist\" aria-label=\"课程难度层级\">\n            <button class=\"tier-tab is-selected\" role=\"tab\" aria-selected=\"true\" data-tier=\"A\" type=\"button\">A 层难度</button>\n            <button class=\"tier-tab\" role=\"tab\" aria-selected=\"false\" data-tier=\"B\" type=\"button\">B 层难度</button>\n            <button class=\"tier-tab\" role=\"tab\" aria-selected=\"false\" data-tier=\"C\" type=\"button\">C 层难度</button>\n          </div>\n          <div class=\"tier-card-stage\" id=\"tierStage\" data-active-tier=\"A\">\n            <div class=\"tier-panel is-visible\" role=\"tabpanel\" data-panel=\"A\">\n              <span class=\"tier-panel__badge\">A 档难度 · 同一教学主题</span>\n              <h3 class=\"tier-panel__title\">面向不同能力梯度的定制支持（A 档）</h3>\n              <p class=\"tier-panel__text\">\n                围绕同一生活主题，针对学生的认知、理解、操作与表达差异调整内容密度与互动引导方式，让不同起点的孩子都能参与同一堂课。\n              </p>\n            </div>\n            <div class=\"tier-panel\" role=\"tabpanel\" data-panel=\"B\">\n              <span class=\"tier-panel__badge\">B 档难度 · 同一教学主题</span>\n              <h3 class=\"tier-panel__title\">面向不同能力梯度的定制支持（B 档）</h3>\n              <p class=\"tier-panel__text\">\n                结合文字说明、语音提示、视频演示与适度交互环节，在理解与动手操作之间取得平衡，方便教师按课堂上不同学生的状态灵活切换。\n              </p>\n            </div>\n            <div class=\"tier-panel\" role=\"tabpanel\" data-panel=\"C\">\n              <span class=\"tier-panel__badge\">C 档难度 · 同一教学主题</span>\n              <h3 class=\"tier-panel__title\">面向不同能力梯度的定制支持（C 档）</h3>\n              <p class=\"tier-panel__text\">\n                与 A、B 版本保持同一生活课题，但在教学结构、提示粒度与操作环节上做针对性分层适配，实现 10 节课 × 3 档层级的完整覆盖。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- Paperclip Note: Why Local HTML? -->\n        <aside class=\"atelier-memo\" aria-label=\"为什么选择本地 HTML 交付\">\n          <svg class=\"atelier-memo__clip\" viewBox=\"0 0 28 48\" fill=\"none\" aria-hidden=\"true\">\n            <path d=\"M9 14 V34 C9 40 19 40 19 34 V10 C19 4 6 4 6 11 V31\"\n                  stroke=\"#8A6830\" stroke-width=\"2\" stroke-linecap=\"round\" />\n          </svg>\n          <h3 class=\"atelier-memo__title\">为什么选择本地 HTML 作为交付形式？</h3>\n          <p class=\"atelier-memo__p\">\n            主要考虑实际使用的便利性。课程可以通过<strong>浏览器在本地打开，支持离线使用</strong>，不必依赖持续联网，也能减少安装专用软件带来的操作负担。\n          </p>\n          <p class=\"atelier-memo__p\">\n            对学校而言，课程交付后能够<strong>保留在本地，方便教师反复使用</strong>。\n          </p>\n        </aside>\n      </div>\n\n      <p class=\"prose-p\" style=\"margin: 24px 0 12px;\">课程包含以下四类多模态内容：</p>\n\n      <!-- 4 Multimodal Vignette Cards (2x2 on Mobile, 4-Across on Desktop) -->\n      <div class=\"modality-grid\">\n        <article class=\"modality-card\">\n          <div class=\"modality-card__icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 36 36\" fill=\"none\">\n              <rect x=\"6\" y=\"5\" width=\"22\" height=\"26\" rx=\"2\" fill=\"#F7E7BE\" transform=\"translate(2,2)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" filter=\"url(#ink-nib)\">\n                <rect x=\"6\" y=\"5\" width=\"22\" height=\"26\" rx=\"2\" fill=\"#FCF9F2\" />\n                <path d=\"M11 12 H23 M11 17 H23 M11 22 H18\" />\n              </g>\n            </svg>\n          </div>\n          <h3 class=\"modality-card__title\">文字内容</h3>\n          <p class=\"modality-card__desc\">教学说明、知识呈现及操作提示。</p>\n        </article>\n\n        <article class=\"modality-card\">\n          <div class=\"modality-card__icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 36 36\" fill=\"none\">\n              <circle cx=\"18\" cy=\"18\" r=\"12\" fill=\"#F2DAD2\" transform=\"translate(2,2)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <path d=\"M9 15 H14 L20 10 V26 L14 21 H9 Z\" fill=\"#FCF9F2\" />\n                <path d=\"M24 14 C26 16 26 20 24 22 M27 11 C30 15 30 21 27 25\" stroke=\"#C25941\" />\n              </g>\n            </svg>\n          </div>\n          <h3 class=\"modality-card__title\">音频内容</h3>\n          <p class=\"modality-card__desc\">配音、语音提示等。</p>\n        </article>\n\n        <article class=\"modality-card\">\n          <div class=\"modality-card__icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 36 36\" fill=\"none\">\n              <rect x=\"5\" y=\"8\" width=\"26\" height=\"20\" rx=\"3\" fill=\"#D8E4F2\" transform=\"translate(2,2)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <rect x=\"5\" y=\"8\" width=\"26\" height=\"20\" rx=\"3\" fill=\"#FCF9F2\" />\n                <polygon points=\"15,13 23,18 15,23\" fill=\"#96B3D6\" />\n              </g>\n            </svg>\n          </div>\n          <h3 class=\"modality-card__title\">视频内容</h3>\n          <p class=\"modality-card__desc\">辅助理解教学知识的视听材料。</p>\n        </article>\n\n        <article class=\"modality-card\">\n          <div class=\"modality-card__icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 36 36\" fill=\"none\">\n              <circle cx=\"18\" cy=\"14\" r=\"9\" fill=\"#DCE9DA\" transform=\"translate(1,1)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <circle cx=\"18\" cy=\"13\" r=\"5\" stroke=\"#557653\" stroke-dasharray=\"2 2\" />\n                <path d=\"M18 13 V26 M18 19 C21 19 25 21 25 26 V29 H13 V23 C13 21 15 20 18 21\" fill=\"#FCF9F2\" />\n              </g>\n            </svg>\n          </div>\n          <h3 class=\"modality-card__title\">互动内容</h3>\n          <p class=\"modality-card__desc\">可供学生操作和参与的数字化学习环节。</p>\n        </article>\n      </div>\n\n      <!-- 10 Everyday Digital-Life Courses Illustrated Stamp Shelf -->\n      <div class=\"course-shelf-head\">\n        <h3 class=\"course-shelf-title\">贴近日常生活的 10 节定制课</h3>\n        <span class=\"course-shelf-sub\">每节 A/B/C 三档</span>\n      </div>\n\n      <div class=\"stamp-grid\">\n        <!-- Course 1: 初识网络与生活 -->\n        <div class=\"course-stamp\">\n          <div class=\"course-stamp__art\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 68 56\" fill=\"none\">\n              <circle cx=\"35\" cy=\"28\" r=\"19\" fill=\"#D8E4F2\" filter=\"url(#gouache-edge)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <rect x=\"19\" y=\"15\" width=\"30\" height=\"26\" rx=\"2\" fill=\"#FCF9F2\" />\n                <path d=\"M19 28 H49 M34 15 V41\" opacity=\"0.45\" />\n                <path d=\"M26 11 C31 7 37 7 42 11\" stroke=\"#C25941\" />\n                <path d=\"M29 14 C32 11.5 36 11.5 39 14\" stroke=\"#C25941\" />\n              </g>\n            </svg>\n          </div>\n          <span class=\"course-stamp__num\">课程 01</span>\n          <p class=\"course-stamp__name\">《初识网络与生活》</p>\n        </div>\n\n        <!-- Course 2: 线上购衣 -->\n        <div class=\"course-stamp\">\n          <div class=\"course-stamp__art\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 68 56\" fill=\"none\">\n              <path d=\"M22 18 L13 25 L17 32 L23 28 V45 H45 V28 L51 32 L55 25 L46 18 Z\" fill=\"#F2DAD2\" transform=\"translate(2,2)\" filter=\"url(#gouache-edge)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <path d=\"M34 9 C36 9 37 11 35 12 L34 14 M26 18 L34 14 L42 18\" />\n                <path d=\"M23 18 L13 25 L17 31 L23 27 V44 H45 V27 L51 31 L55 25 L45 18 C41 21 27 21 23 18 Z\" fill=\"#FCF9F2\" />\n                <path d=\"M24 25 H44 M24 30 H44 M24 35 H44 M24 40 H44\" stroke=\"#33588A\" stroke-width=\"1.2\" />\n              </g>\n            </svg>\n          </div>\n          <span class=\"course-stamp__num\">课程 02</span>\n          <p class=\"course-stamp__name\">《线上购衣》</p>\n        </div>\n\n        <!-- Course 3: 线上订餐 -->\n        <div class=\"course-stamp\">\n          <div class=\"course-stamp__art\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 68 56\" fill=\"none\">\n              <path d=\"M16 28 C16 42 52 42 52 28 Z\" fill=\"#F7E7BE\" transform=\"translate(2,2)\" filter=\"url(#gouache-edge)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <path d=\"M26 13 C24 17 28 19 26 23 M34 11 C32 15 36 18 34 22 M42 14 C40 18 44 20 42 23\" stroke=\"#C25941\" />\n                <path d=\"M16 27 H52 C51 40 42 44 34 44 C26 44 17 40 16 27 Z\" fill=\"#FCF9F2\" />\n                <path d=\"M26 44 H42\" stroke-width=\"1.6\" />\n                <path d=\"M40 27 L50 18\" stroke-width=\"1.5\" />\n              </g>\n            </svg>\n          </div>\n          <span class=\"course-stamp__num\">课程 03</span>\n          <p class=\"course-stamp__name\">《线上订餐》</p>\n        </div>\n\n        <!-- Course 4: 线上买菜 -->\n        <div class=\"course-stamp\">\n          <div class=\"course-stamp__art\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 68 56\" fill=\"none\">\n              <path d=\"M17 27 H51 L46 44 H22 Z\" fill=\"#F7E7BE\" transform=\"translate(2,2)\" filter=\"url(#gouache-edge)\" />\n              <circle cx=\"29\" cy=\"24\" r=\"6\" fill=\"#E39A86\" />\n              <path d=\"M36 26 L43 14 L47 26 Z\" fill=\"#DCE9DA\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <path d=\"M24 26 C24 14 44 14 44 26\" />\n                <circle cx=\"28\" cy=\"24\" r=\"5\" fill=\"#E39A86\" />\n                <path d=\"M36 26 L41 15 L45 26\" fill=\"#98B894\" />\n                <path d=\"M17 26 H51 L46 44 H22 Z\" fill=\"#FCF9F2\" fill-opacity=\"0.65\" />\n                <path d=\"M21 32 H47 M22 38 H46 M29 26 L30 44 M39 26 L38 44\" opacity=\"0.65\" />\n              </g>\n            </svg>\n          </div>\n          <span class=\"course-stamp__num\">课程 04</span>\n          <p class=\"course-stamp__name\">《线上买菜》</p>\n        </div>\n\n        <!-- Course 5: 线上打车 -->\n        <div class=\"course-stamp\">\n          <div class=\"course-stamp__art\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 68 56\" fill=\"none\">\n              <path d=\"M14 31 L20 21 H44 L51 31 H55 V40 H12 V31 Z\" fill=\"#F7E7BE\" transform=\"translate(2,2)\" filter=\"url(#gouache-edge)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <rect x=\"29\" y=\"16\" width=\"9\" height=\"4\" rx=\"1\" fill=\"#C25941\" />\n                <path d=\"M13 30 L20 20 H44 L50 30 H55 C56 30 57 32 57 34 V39 H11 V33 C11 31 12 30 13 30 Z\" fill=\"#F9E395\" />\n                <path d=\"M22 23 L18 30 H32 V23 Z M35 23 V30 H47 L42 23 Z\" fill=\"#FCF9F2\" />\n                <circle cx=\"21\" cy=\"40\" r=\"4.5\" fill=\"#FCF9F2\" />\n                <circle cx=\"46\" cy=\"40\" r=\"4.5\" fill=\"#FCF9F2\" />\n              </g>\n            </svg>\n          </div>\n          <span class=\"course-stamp__num\">课程 05</span>\n          <p class=\"course-stamp__name\">《线上打车》</p>\n        </div>\n\n        <!-- Course 6: 线上医疗 -->\n        <div class=\"course-stamp\">\n          <div class=\"course-stamp__art\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 68 56\" fill=\"none\">\n              <rect x=\"17\" y=\"16\" width=\"34\" height=\"26\" rx=\"4\" fill=\"#DCE9DA\" transform=\"translate(2,2)\" filter=\"url(#gouache-edge)\" />\n              <g stroke=\"#27231F\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                <path d=\"M27 16 V12 H41 V16\" />\n                <rect x=\"17\" y=\"16\" width=\"34\" height=\"26\" rx=\"4\" fill=\"#FCF9F2\" />\n                <path d=\"M32 23 H36 V27 H40 V31 H36 V35 H32 V31 H28 V27 H32 Z\" fill=\"#E39A86\" stroke=\"#C25941\" />\n              </g>\n            </svg>\n          </div>\n          <span class=\"course-stamp__num\">课程 06</span>\n          <p class=\"course-stamp__name\">《线上医疗》</p>\n        </div>\n\n        <!-- Remaining 4 Courses Summary Bar -->\n        <div class=\"course-stamp course-stamp--more\">\n          <div>\n            <span class=\"course-stamp__num\">课程 07 – 10</span>\n            <p class=\"course-stamp__name\">以及其余 4 节定制互动课程</p>\n          </div>\n          <span class=\"course-stamp__tag\">共 10 节内容</span>\n        </div>\n      </div>\n    </section>\n\n    <div class=\"deckle-divider\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 490 14\" preserveAspectRatio=\"none\">\n        <path d=\"M0 14 L0 6 Q24 2 48 7 T96 6 T144 7 T192 5 T240 7 T288 6 T336 7 T384 5 T432 7 T490 6 L490 14 Z\" fill=\"#EFE7D6\" />\n      </svg>\n    </div>\n\n    <!-- ====================================================================\n         CHAPTER 04 · AI 工具和流程：如何完成制作？\n         ==================================================================== -->\n    <section class=\"chapter chapter--tinted-warm\" id=\"sec-workflow\">\n      <div class=\"workflow-layout\">\n        <div class=\"workflow-layout__side\">\n          <div class=\"chapter-header\">\n            <div class=\"chapter-rubric\">\n              <span class=\"chapter-num-badge chapter-num-badge--sage\">04</span>\n              <span class=\"chapter-sub-cn\">辅助工具与五步实施路径</span>\n            </div>\n            <h2 class=\"chapter-title\">AI 工具和流程：如何完成制作？</h2>\n          </div>\n\n          <p class=\"prose-p\">\n            本项目采用 <span class=\"gouache-hl\">AI 辅助内容生产与代码开发</span>的工作方式，围绕特殊教育场景进行课程设计和交付。\n          </p>\n\n          <!-- Codex Tool Seal Card -->\n          <div class=\"codex-colophon\">\n            <div class=\"codex-colophon__seal\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 54 54\" fill=\"none\">\n                <circle cx=\"28\" cy=\"28\" r=\"22\" fill=\"#F7E7BE\" filter=\"url(#gouache-edge)\" />\n                <g stroke=\"#27231F\" stroke-width=\"1.35\" stroke-linecap=\"round\" stroke-linejoin=\"round\" filter=\"url(#ink-nib)\">\n                  <circle cx=\"27\" cy=\"27\" r=\"22\" stroke-dasharray=\"3 2.5\" />\n                  <circle cx=\"27\" cy=\"27\" r=\"18\" fill=\"#FCF9F2\" />\n                  <path d=\"M18 23 L14 27 L18 31 M36 23 L40 27 L36 31\" stroke=\"#33588A\" />\n                  <path d=\"M27 16 L31 26 L27 37 L23 26 Z\" fill=\"#E39A86\" />\n                  <circle cx=\"27\" cy=\"26\" r=\"1.4\" fill=\"#27231F\" />\n                </g>\n              </svg>\n            </div>\n            <div>\n              <span class=\"codex-colophon__label\">主力 AI 辅助开发工具</span>\n              <h3 class=\"codex-colophon__title\">Codex 辅助制作</h3>\n              <p class=\"codex-colophon__desc\">项目采用了 AI 辅助制作的方式，主要用的是 Codex，高效转化多模态素材与本地 HTML 交互逻辑。</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"workflow-layout__steps\">\n          <p class=\"prose-p workflow-steps-lead\">整体流程可以概括为五个步骤：</p>\n\n          <ol class=\"workflow-trail\">\n            <li class=\"workflow-step\">\n              <span class=\"workflow-step__marker\">1</span>\n              <h3 class=\"workflow-step__title\">第一步：需求分析与教学设计</h3>\n              <p class=\"workflow-step__desc\">梳理学校的教学需求、学生能力差异和交付要求，确定每节课的教学目标、内容结构及 A、B、C 三档难度。</p>\n            </li>\n\n            <li class=\"workflow-step\">\n              <span class=\"workflow-step__marker\">2</span>\n              <h3 class=\"workflow-step__title\">第二步：课程内容制作</h3>\n              <p class=\"workflow-step__desc\">根据教学目标组织文字、音频、视频、图片等素材，形成适合不同学习能力的多模态教学内容。</p>\n            </li>\n\n            <li class=\"workflow-step\">\n              <span class=\"workflow-step__marker\">3</span>\n              <h3 class=\"workflow-step__title\">第三步：HTML 互动课程开发</h3>\n              <p class=\"workflow-step__desc\">将课程内容转化为浏览器可运行的 HTML 页面，整合多媒体素材和互动功能，形成可独立使用的课程文件。</p>\n            </li>\n\n            <li class=\"workflow-step\">\n              <span class=\"workflow-step__marker\">4</span>\n              <h3 class=\"workflow-step__title\">第四步：分层适配与功能检查</h3>\n              <p class=\"workflow-step__desc\">检查不同难度版本的内容与交互方式，并验证页面、媒体资源和本地运行功能。</p>\n            </li>\n\n            <li class=\"workflow-step\">\n              <span class=\"workflow-step__marker\">5</span>\n              <h3 class=\"workflow-step__title\">第五步：分批交付与反馈调整</h3>\n              <p class=\"workflow-step__desc\">根据项目交付安排，分批提交课程成果，并配合学校进行后续沟通和调整。</p>\n            </li>\n          </ol>\n        </div>\n      </div>\n    </section>\n\n    <div class=\"deckle-divider\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 490 14\" preserveAspectRatio=\"none\" style=\"background:#EFE7D6\">\n        <path d=\"M0 14 L0 6 Q24 11 48 6 T96 7 T144 5 T192 7 T240 5 T288 7 T336 6 T384 8 T432 6 T490 7 L490 14 Z\" fill=\"#F7F2E7\" />\n      </svg>\n    </div>\n\n    <!-- ====================================================================\n         CHAPTER 05 · 周期和分工：做了多久？谁来做？\n         ==================================================================== -->\n    <section class=\"chapter\" id=\"sec-team\">\n      <div class=\"team-top-row\">\n        <div class=\"chapter-header\">\n          <div class=\"chapter-rubric\">\n            <span class=\"chapter-num-badge\">05</span>\n            <span class=\"chapter-sub-cn\">实施排期与轻量化团队协作</span>\n          </div>\n          <h2 class=\"chapter-title\">周期和分工：做了多久？谁来做？</h2>\n        </div>\n\n        <!-- Tear-off Calendar Card -->\n        <div class=\"calendar-row\" aria-label=\"项目启动时间与周期\">\n          <div class=\"eph-leaf\">\n            <div class=\"eph-leaf__top\">2026 年 9 月</div>\n            <div class=\"eph-leaf__day\">11</div>\n            <div class=\"eph-leaf__sub\">项目正式启动</div>\n          </div>\n          <div class=\"calendar-summary\">\n            <p class=\"calendar-summary__big\">项目周期调整约 35 天</p>\n            <p class=\"calendar-summary__note\">\n              由<strong>北京千赞科技有限公司</strong>承接，采用小型协作团队的方式敏捷实施。\n            </p>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"team-dossier\">\n        <!-- Project Lead: 吴熳 -->\n        <article class=\"role-card role-card--lead\">\n          <span class=\"role-card__eyebrow\">项目负责人 · 需求与交付统筹</span>\n          <h3 class=\"role-card__name\">吴熳（我）</h3>\n          <p class=\"prose-p\" style=\"font-size:14.5px; margin-bottom:6px;\">\n            主要负责前端客户对接与全周期把控，串联学校实际教学诉求与技术实现：\n          </p>\n          <div class=\"duty-tags\">\n            <span class=\"duty-tag\">甲方需求沟通</span>\n            <span class=\"duty-tag\">项目方案</span>\n            <span class=\"duty-tag\">交付范围确认</span>\n            <span class=\"duty-tag\">合作协调</span>\n            <span class=\"duty-tag\">进度管理</span>\n            <span class=\"duty-tag\">验收沟通</span>\n          </div>\n        </article>\n\n        <!-- Partner Developer -->\n        <article class=\"role-card role-card--dev\">\n          <span class=\"role-card__eyebrow\">技术协作 · 研发与维护支持</span>\n          <h3 class=\"role-card__name\">合作开发人员</h3>\n          <p class=\"prose-p\" style=\"font-size:14.5px; margin-bottom:6px;\">\n            具体的课程开发和技术交付由合作开发人员参与完成，协同保障落地体验：\n          </p>\n          <div class=\"duty-tags\">\n            <span class=\"duty-tag\">互动课程开发</span>\n            <span class=\"duty-tag\">技术交付</span>\n            <span class=\"duty-tag\">分批交付推进</span>\n            <span class=\"duty-tag\">技术维护</span>\n            <span class=\"duty-tag\">使用答疑</span>\n          </div>\n        </article>\n      </div>\n\n      <p class=\"prose-p\" style=\"margin-top:18px;\">\n        这是一个典型的<span class=\"gouache-hl--rose\">轻量化 AI 项目协作案例</span>：通过项目负责人<strong>吴熳</strong>整合需求、教学内容与技术开发能力，为学校提供定制化交付。\n      </p>\n    </section>\n\n    <div class=\"deckle-divider\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 490 14\" preserveAspectRatio=\"none\">\n        <path d=\"M0 14 L0 6 Q24 2 48 7 T96 6 T144 7 T192 5 T240 7 T288 6 T336 7 T384 5 T432 7 T490 6 L490 14 Z\" fill=\"#EFE7D6\" />\n      </svg>\n    </div>\n\n    <!-- ====================================================================\n         CHAPTER 06 · 结果：实际取得了什么成果？\n         ==================================================================== -->\n    <section class=\"chapter chapter--tinted-warm\" id=\"sec-outcome\">\n      <div class=\"outcome-layout\">\n        <div class=\"outcome-layout__quote\">\n          <div class=\"chapter-header\">\n            <div class=\"chapter-rubric\">\n              <span class=\"chapter-num-badge chapter-num-badge--ochre\">06</span>\n              <span class=\"chapter-sub-cn\">交付成果与课堂真实回响</span>\n            </div>\n            <h2 class=\"chapter-title\">结果：实际取得了什么成果？</h2>\n          </div>\n\n          <p class=\"prose-p\">\n            项目取得了比较明确的交付成果和客户认可。\n          </p>\n\n          <!-- Lined Postcard: Teacher's Verbatim Quote -->\n          <blockquote class=\"postcard-quote\">\n            <div class=\"postcard-quote__header\">\n              <span class=\"postcard-quote__label\">课堂实测回响 · 一线教师反馈原话</span>\n              <div class=\"postcard-quote__stamp\" aria-hidden=\"true\">\n                <svg viewBox=\"0 0 44 50\" fill=\"none\">\n                  <rect x=\"3\" y=\"3\" width=\"38\" height=\"44\" fill=\"#F2DAD2\" stroke=\"#C25941\" stroke-width=\"1.2\" stroke-dasharray=\"2.5 2\" />\n                  <rect x=\"7\" y=\"7\" width=\"30\" height=\"36\" stroke=\"#27231F\" stroke-width=\"0.8\" fill=\"#FCF9F2\" />\n                  <path d=\"M22 37 C22 27 23 19 26 14\" stroke=\"#557653\" stroke-width=\"1.3\" stroke-linecap=\"round\" />\n                  <path d=\"M22 30 C16 28 15 22 19 21 C22 22 23 26 22 30 Z\" fill=\"#98B894\" stroke=\"#27231F\" stroke-width=\"0.9\" />\n                  <path d=\"M23 24 C29 22 31 17 27 16 C24 17 23 21 23 24 Z\" fill=\"#98B894\" stroke=\"#27231F\" stroke-width=\"0.9\" />\n                </svg>\n              </div>\n            </div>\n            <p class=\"postcard-quote__text\">\n              <span class=\"postcard-quote__mark\" aria-hidden=\"true\">“</span>课堂中让学生都尝试操作各个模块了，基本没什么问题，后续又反馈，学生用得很顺畅。\n            </p>\n            <footer class=\"postcard-quote__footer\">—— 南方某康复学校 · 授课教师课堂实测反馈</footer>\n          </blockquote>\n        </div>\n\n        <!-- 5 Concrete Outcomes -->\n        <ol class=\"outcome-list\">\n          <li class=\"outcome-card\">\n            <div class=\"outcome-card__check\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 28 28\" fill=\"none\">\n                <circle cx=\"15\" cy=\"15\" r=\"11\" fill=\"#F7E7BE\" />\n                <circle cx=\"14\" cy=\"14\" r=\"10.5\" stroke=\"#27231F\" stroke-width=\"1.25\" filter=\"url(#ink-nib)\" />\n                <path d=\"M9.5 14.5 L12.8 17.8 L19 10.8\" stroke=\"#C25941\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n              </svg>\n            </div>\n            <div>\n              <h3 class=\"outcome-card__title\">1. 真实付费订单</h3>\n              <p class=\"outcome-card__desc\">第一期项目合同金额为<strong> 5 位数</strong>，约定交付 10 节数字化互动课程，每节设置 A、B、C 三个难度层级。</p>\n            </div>\n          </li>\n\n          <li class=\"outcome-card\">\n            <div class=\"outcome-card__check\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 28 28\" fill=\"none\">\n                <circle cx=\"15\" cy=\"15\" r=\"11\" fill=\"#D8E4F2\" />\n                <circle cx=\"14\" cy=\"14\" r=\"10.5\" stroke=\"#27231F\" stroke-width=\"1.25\" filter=\"url(#ink-nib)\" />\n                <path d=\"M9.5 14.5 L12.8 17.8 L19 10.8\" stroke=\"#33588A\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n              </svg>\n            </div>\n            <div>\n              <h3 class=\"outcome-card__title\">2. 阶段性交付完成</h3>\n              <p class=\"outcome-card__desc\">项目已经完成第一批交付，并按照合同安排推进后续课程制作。</p>\n            </div>\n          </li>\n\n          <li class=\"outcome-card\">\n            <div class=\"outcome-card__check\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 28 28\" fill=\"none\">\n                <circle cx=\"15\" cy=\"15\" r=\"11\" fill=\"#F2DAD2\" />\n                <circle cx=\"14\" cy=\"14\" r=\"10.5\" stroke=\"#27231F\" stroke-width=\"1.25\" filter=\"url(#ink-nib)\" />\n                <path d=\"M9.5 14.5 L12.8 17.8 L19 10.8\" stroke=\"#C25941\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n              </svg>\n            </div>\n            <div>\n              <h3 class=\"outcome-card__title\">3. 客户高度满意</h3>\n              <p class=\"outcome-card__desc\">学校对已经交付的课程效果非常满意，认可课程的呈现形式和实际教学适用性。</p>\n            </div>\n          </li>\n\n          <li class=\"outcome-card\">\n            <div class=\"outcome-card__check\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 28 28\" fill=\"none\">\n                <circle cx=\"15\" cy=\"15\" r=\"11\" fill=\"#DCE9DA\" />\n                <circle cx=\"14\" cy=\"14\" r=\"10.5\" stroke=\"#27231F\" stroke-width=\"1.25\" filter=\"url(#ink-nib)\" />\n                <path d=\"M9.5 14.5 L12.8 17.8 L19 10.8\" stroke=\"#557653\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n              </svg>\n            </div>\n            <div>\n              <h3 class=\"outcome-card__title\">4. 获得后续合作机会</h3>\n              <p class=\"outcome-card__desc\">基于第一期的交付效果，学校决定将<strong>第二期剩余的部分康复课程内容</strong>继续交由我们团队制作。</p>\n            </div>\n          </li>\n\n          <li class=\"outcome-card\">\n            <div class=\"outcome-card__check\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 28 28\" fill=\"none\">\n                <circle cx=\"15\" cy=\"15\" r=\"11\" fill=\"#F7E7BE\" />\n                <circle cx=\"14\" cy=\"14\" r=\"10.5\" stroke=\"#27231F\" stroke-width=\"1.25\" filter=\"url(#ink-nib)\" />\n                <path d=\"M9.5 14.5 L12.8 17.8 L19 10.8\" stroke=\"#C25941\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n              </svg>\n            </div>\n            <div>\n              <h3 class=\"outcome-card__title\">5. 形成可复用的交付经验</h3>\n              <p class=\"outcome-card__desc\">团队积累了特殊教育场景下的分层课程设计、多模态内容制作和本地 HTML 互动课程开发经验。</p>\n            </div>\n          </li>\n        </ol>\n      </div>\n    </section>\n\n    <!-- ====================================================================\n         尾署\n         ==================================================================== -->\n    <footer class=\"colophon-footer\">\n      <div class=\"colophon-ornament\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 96 36\" fill=\"none\">\n          <path d=\"M10 18 H36 M60 18 H86\" stroke=\"#27231F\" stroke-opacity=\"0.35\" stroke-width=\"1\" stroke-linecap=\"round\" />\n          <circle cx=\"48\" cy=\"18\" r=\"7\" fill=\"#F7E7BE\" />\n          <path d=\"M44 21 L48 11 L52 21 Z\" stroke=\"#27231F\" stroke-width=\"1.2\" fill=\"#E39A86\" />\n        </svg>\n      </div>\n      <p class=\"colophon-title\">灯下白 · FDE 案例展示</p>\n      <p class=\"colophon-meta\">\n        南方康复学校脑瘫儿童课程定制项目<br />\n        承接方：北京千赞科技有限公司 · 项目负责人：吴熳\n      </p>\n    </footer>\n  </main>\n\n  <script>\n(function () {\n  \"use strict\";\n\n  // 1. Top Reading Progress Hairline\n  var readingBar = document.getElementById(\"readingBar\");\n  function updateProgress() {\n    if (!readingBar) return;\n    var scrollTop = window.scrollY || document.documentElement.scrollTop;\n    var docHeight =\n      document.documentElement.scrollHeight -\n      document.documentElement.clientHeight;\n    var pct =\n      docHeight > 0\n        ? Math.min(100, Math.max(0, (scrollTop / docHeight) * 100))\n        : 0;\n    readingBar.style.width = pct.toFixed(1) + \"%\";\n  }\n\n  // 2. Interactive A / B / C Difficulty Folder Tabs\n  var tierTabs = document.querySelectorAll(\".tier-tab\");\n  var tierStage = document.getElementById(\"tierStage\");\n  var tierPanels = document.querySelectorAll(\".tier-panel\");\n\n  tierTabs.forEach(function (tab) {\n    tab.addEventListener(\"click\", function () {\n      var target = tab.getAttribute(\"data-tier\");\n      if (!target) return;\n\n      tierTabs.forEach(function (t) {\n        var active = t === tab;\n        t.classList.toggle(\"is-selected\", active);\n        t.setAttribute(\"aria-selected\", active ? \"true\" : \"false\");\n      });\n\n      if (tierStage) {\n        tierStage.setAttribute(\"data-active-tier\", target);\n      }\n\n      tierPanels.forEach(function (panel) {\n        var match = panel.getAttribute(\"data-panel\") === target;\n        panel.classList.toggle(\"is-visible\", match);\n      });\n    });\n  });\n\n  // 3. Sticky Chapter Ribbon Active Highlight (Accurate Viewport Tracking)\n  var navLinks = document.querySelectorAll(\".chapter-nav__link\");\n  var sections = [];\n\n  navLinks.forEach(function (link) {\n    var href = link.getAttribute(\"href\");\n    if (href && href.charAt(0) === \"#\") {\n      var sec = document.querySelector(href);\n      if (sec) sections.push({ id: href, el: sec, link: link });\n    }\n  });\n\n  function updateActiveChapter() {\n    if (!sections.length) return;\n    var scrollBottom =\n      (window.scrollY || document.documentElement.scrollTop) +\n      window.innerHeight;\n    var docHeight = document.documentElement.scrollHeight;\n\n    var current = sections[0];\n    if (docHeight - scrollBottom <= 24) {\n      current = sections[sections.length - 1];\n    } else {\n      for (var i = 0; i < sections.length; i++) {\n        var rect = sections[i].el.getBoundingClientRect();\n        if (rect.top <= 160) {\n          current = sections[i];\n        }\n      }\n    }\n\n    sections.forEach(function (item) {\n      item.link.classList.toggle(\"is-active\", item === current);\n    });\n  }\n\n  function onScroll() {\n    updateProgress();\n    updateActiveChapter();\n  }\n\n  window.addEventListener(\"scroll\", onScroll, { passive: true });\n  window.addEventListener(\"resize\", onScroll, { passive: true });\n  onScroll();\n})();\n\n  </script>\n</body>\n</html>\n";

export function GET(): Response {
  return new Response(PAGE_HTML, {
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'public, max-age=3600, s-maxage=86400',
    },
  });
}
